  function searchPage(){return shell(`${pageHeader("AUTHORIZED DISCOVERY",t("search"),state.lang==="ar"?"بحث داخل البيانات الوصفية والقضايا وعهدة الحيازة مع تطبيق صلاحيات المؤسسة.":"Search evidence metadata, case context and custody history with tenant-aware authorization.",btn(state.lang==="ar"?"مرشحات متقدمة":"Advanced filters","filters","","filter"))}<div class="data-tools"><div class="searchbox">${icon("search")}<input value="access review" placeholder="Search evidence, cases and custody actors"/></div><button class="filter-pill active">All sources</button><button class="filter-pill">Verified only</button><button class="filter-pill">Legal Hold</button><button class="filter-pill">Last 30 days</button></div><article class="card"><header class="card-header"><div><h3>${state.lang==="ar"?"نتائج البحث":"Search results"}</h3><p>24 matches found across fictional records</p></div>${badge("Authorization filtered","green")}</header><div class="card-body flush">${evidenceTable(D.evidence)}</div></article>`,"search")}
  function exportsPage(){const e=selectedEvidence();return shell(`${pageHeader("PORTABLE VERIFICATION",t("exports"),state.lang==="ar"?"إنشاء حزم أدلة تحتوي على البيان، البصمات، عهدة الحيازة، ونتائج التحقق.":"Build portable evidence packages containing manifests, fingerprints, custody history and verification results.",`${btn(t("certificate"),"download-certificate","primary","download")}${btn(t("evidencePackage"),"generate-package","dark","package")}`)}<section class="grid two"><article class="card"><header class="card-header"><div><h3>${state.lang==="ar"?"منشئ حزمة الدليل":"Evidence package builder"}</h3><p>${e.id} · ${e.title}</p></div>${badge("Ready","green")}</header><div class="card-body"><div class="control-grid" style="grid-template-columns:1fr">${[["Original evidence object","Included and checksum-referenced","file"],["Manifest","Evidence metadata and object inventory","document"],["Integrity report","SHA-512 result and verification timestamp","fingerprint"],["Chain of custody","Signed action, actor and time sequence","link"],["Offline verification guide","Portable verification workflow","shield-check"],["Integrity certificate","Downloadable PDF summary","download"]].map(c=>`<div class="control-item"><div class="control-icon">${icon(c[2])}</div><div><strong>${c[0]}</strong><small>${c[1]}</small></div>${badge("Included","green")}</div>`).join("")}</div></div></article><article class="certificate-card"><img class="certificate-logo" src="assets/logo-wordmark.svg" alt="RM TraceVault"/><h3>${state.lang==="ar"?"تحقق مستقل وقابل للنقل":"Portable independent verification"}</h3><p>${state.lang==="ar"?"توضح تجربة العرض كيف تُفحص الحزمة دون الاعتماد على جلسة المستخدم داخل المنصة.":"The demonstration shows how a recipient can inspect the package without relying on the original platform session."}</p><div class="certificate-fields"><div class="certificate-field"><span>Manifest</span><strong>VERIFIED</strong></div><div class="certificate-field"><span>SHA-512</span><strong>MATCH</strong></div><div class="certificate-field"><span>Custody signatures</span><strong>VALID</strong></div><div class="certificate-field"><span>Package</span><strong>COMPLETE</strong></div></div>${btn(t("certificate"),"download-certificate","primary","download")}</article></section><article class="card"><header class="card-header"><div><h3>${state.lang==="ar"?"سجل التصدير":"Recent export packages"}</h3><p>${state.lang==="ar"?"أمثلة افتراضية على الحزم":"Fictional package records"}</p></div></header><div class="card-body flush"><div class="table-wrap"><table class="data-table"><thead><tr><th>Package</th><th>Case</th><th>Evidence</th><th>Size</th><th>Requested by</th><th>Created</th><th>Status</th></tr></thead><tbody>${D.exports.map(x=>`<tr><td><strong>${esc(x.id)}</strong></td><td>${esc(x.caseId)}</td><td>${x.evidence}</td><td>${esc(x.size)}</td><td>${esc(x.requestedBy)}</td><td>${esc(x.created)}</td><td>${badge(x.status,"green")}</td></tr>`).join("")}</tbody></table></div></div></article>`,"exports")}
